create table alert_record (read_flag boolean, created_at timestamp(6), id bigint generated by default as identity, job_id bigint, owner_id bigint, event varchar(255) not null, job_name varchar(255), level varchar(255) not null, message TEXT not null, primary key (id));
create table app_user (enabled boolean not null, token_version integer, created_at timestamp(6), id bigint generated by default as identity, last_login_at timestamp(6), last_seen_at timestamp(6), updated_at timestamp(6), status_preference varchar(16) check (status_preference in ('ONLINE','AWAY','BUSY','INVISIBLE','OFFLINE')), signature varchar(200), avatar_key varchar(255), display_name varchar(255), password_hash varchar(255) not null, role varchar(255) not null check (role in ('ADMIN','OPERATOR','VIEWER')), username varchar(255) not null unique, primary key (id));
create table audit_log (created_at timestamp(6), id bigint generated by default as identity, user_id bigint, action varchar(255) not null, detail TEXT, ip varchar(255), target_id varchar(255), target_type varchar(255), username varchar(255), primary key (id));
create table control_registry (enabled boolean, created_at timestamp(6), id bigint generated by default as identity, updated_at timestamp(6), category varchar(255) not null, description TEXT, flink_template TEXT, jar_path varchar(255) not null, name varchar(255) not null, param_schema TEXT, type varchar(255) not null unique, version varchar(255) not null, primary key (id));
create table data_source_connection (credential_configured boolean not null, enabled boolean not null, created_at timestamp(6) not null, id bigint generated by default as identity, owner_id bigint not null, updated_at timestamp(6) not null, version bigint, type varchar(32) not null check (type in ('MYSQL','POSTGRESQL','ORACLE','KAFKA','REDIS','HDFS')), name varchar(128) not null, owner_name varchar(128) not null, config_json TEXT not null, description TEXT, encrypted_credentials TEXT, primary key (id), constraint uk_data_source_owner_name unique (owner_id, name));
create table diagnosis_report (created_at timestamp(6), id bigint generated by default as identity, job_id bigint, owner_id bigint, job_name varchar(64), source varchar(64), trigger varchar(64), root_cause varchar(1000), evidence varchar(4000), suggestions varchar(4000), packet TEXT, param_fixes TEXT, primary key (id));
create table job_definition (online boolean, online_restart_count integer, parallelism integer, schedule_enabled boolean, schedule_max_retries integer, schedule_retries integer, completed_at timestamp(6), confirmed_at timestamp(6), confirmed_by bigint, created_at timestamp(6), id bigint generated by default as identity, last_restart_at timestamp(6), next_fire_time timestamp(6), online_since timestamp(6), owner_id bigint, submitted_at timestamp(6), updated_at timestamp(6), confirmation_status varchar(255) check (confirmation_status in ('NOT_REQUIRED','PENDING','CONFIRMED')), confirmed_by_name varchar(255), cron_expression varchar(255), dag_json TEXT not null, description TEXT, flink_job_id TEXT, name varchar(255) not null, owner_name varchar(255), source varchar(255) check (source in ('MANUAL','AI')), status varchar(255) not null check (status in ('DRAFT','SUBMITTED','RUNNING','COMPLETED','FAILED','CANCELLED','WAITING','BLOCKED')), webhook_url varchar(255), primary key (id));
create table job_dependency (created_at timestamp(6), downstream_job_id bigint not null, id bigint generated by default as identity, upstream_job_id bigint not null, primary key (id), unique (upstream_job_id, downstream_job_id));
create table job_log (id bigint generated by default as identity, job_id bigint not null, timestamp timestamp(6), level varchar(255) not null, message TEXT not null, primary key (id));
create table job_version (parallelism integer, version_no integer, created_at timestamp(6), id bigint generated by default as identity, job_id bigint not null, dag_json TEXT not null, name TEXT, primary key (id));
create table schedule_history (id bigint generated by default as identity, job_id bigint, trigger_time timestamp(6), flink_job_id varchar(255), job_name varchar(255), message TEXT, status varchar(255), primary key (id));
create table trend_point (bp float(53) not null, input_rate float(53) not null, output_rate float(53) not null, id bigint generated by default as identity, job_id bigint not null, t bigint not null, status varchar(16), run_key varchar(64), primary key (id));
create index idx_alert_owner_created on alert_record (owner_id, created_at);
create index idx_alert_read_created on alert_record (read_flag, created_at);
create index idx_data_source_owner on data_source_connection (owner_id);
create index idx_data_source_updated on data_source_connection (updated_at);
